import{_ as a,o as t,c as o,ae as n}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Honey Oatmeal","description":"","frontmatter":{"title":"Honey Oatmeal"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/oatmeal.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/oatmeal.md"}'),r={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/oatmeal.md"};function s(l,e,i,d,p,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="honey-oatmeal" tabindex="-1">Honey Oatmeal <a class="header-anchor" href="#honey-oatmeal" aria-label="Permalink to &quot;Honey Oatmeal&quot;">​</a></h1><p>Honey Oatmeal is an advanced food product made using <strong>Honey</strong> and <strong>Oats</strong>. It is produced in the <strong>Honey Oatmeal Factory</strong> and can be sold for a significant amount of Coins.</p><h2 id="product-information" tabindex="-1">Product Information <a class="header-anchor" href="#product-information" aria-label="Permalink to &quot;Product Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Production Building</td><td>Honey Oatmeal Factory</td></tr><tr><td>Main Ingredients</td><td>Honey &amp; Oats</td></tr><tr><td>Oats Required</td><td>100 Harvested Oats</td></tr><tr><td>Honey Required</td><td>1 Honey Pallet</td></tr><tr><td>Output</td><td>Honey Oatmeal</td></tr><tr><td>Pallet Size</td><td>27 Bundles</td></tr><tr><td>Maximum Sell Value</td><td>87,750 Coins per Pallet</td></tr></tbody></table><p>A full pallet of Honey Oatmeal contains <strong>27 bundles</strong>. Each bundle can sell for up to <strong>3,250 Coins</strong>, giving a maximum pallet value of <strong>87,750 Coins</strong>.</p><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><p>To produce one pallet of Honey Oatmeal, you need:</p><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Honey</td><td>1 Pallet</td></tr><tr><td>Harvested Oats</td><td>100</td></tr></tbody></table><p>One Honey Pallet contains <strong>4 Honey Barrels</strong>, which are consumed by the Honey Oatmeal Factory.</p><blockquote><p><strong>Note:</strong> The factory may currently require <strong>101 Oats to be loaded</strong> because of a floating-point counter issue, although only 100 Oats are ultimately consumed.</p></blockquote><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed production time for Honey Oatmeal is not reliably documented.</p><p>Production requires the player to supply the required Honey and Oats and operate the Honey Oatmeal Factory.</p><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The factory produces <strong>Honey Oatmeal Bundles</strong>.</p><table tabindex="0"><thead><tr><th>Product</th><th>Amount</th></tr></thead><tbody><tr><td>Honey Oatmeal</td><td>27 Bundles per Pallet</td></tr></tbody></table><p>Honey Oatmeal is sold by the bundle rather than having a separate fixed pallet selling price.</p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>The maximum documented selling price is:</p><p><strong>3,250 Coins per Bundle</strong></p><p>A full pallet contains 27 bundles:</p><p><strong>27 × 3,250 = 87,750 Coins</strong></p><table tabindex="0"><thead><tr><th>Product</th><th>Maximum Value</th></tr></thead><tbody><tr><td>1 Bundle</td><td>3,250 Coins</td></tr><tr><td>27 Bundles</td><td>87,750 Coins</td></tr></tbody></table><p>These are maximum documented values and may change with future updates.</p><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To produce Honey Oatmeal, you will need:</p><ul><li><strong>Honey Oatmeal Factory</strong></li><li><strong>Honey</strong></li><li><strong>Honey Factory</strong></li><li><strong>Beehives</strong></li><li><strong>Bees</strong></li><li><strong>Oat Seeds</strong></li><li><strong>Farming equipment</strong></li><li><strong>Suitable transport for Honey pallets</strong></li></ul><p>Oats can be grown using any level of farming equipment and take approximately <strong>8 minutes</strong> to grow without growth multipliers.</p><h2 id="how-to-make-honey-oatmeal" tabindex="-1">How to Make Honey Oatmeal <a class="header-anchor" href="#how-to-make-honey-oatmeal" aria-label="Permalink to &quot;How to Make Honey Oatmeal&quot;">​</a></h2><h3 id="_1-unlock-honey-oatmeal" tabindex="-1">1. Unlock Honey Oatmeal <a class="header-anchor" href="#_1-unlock-honey-oatmeal" aria-label="Permalink to &quot;1. Unlock Honey Oatmeal&quot;">​</a></h3><p>You must unlock the <strong>Honey Oatmeal Farming Goal</strong> before producing Honey Oatmeal. You also need a reliable source of Honey.</p><h3 id="_2-produce-honey" tabindex="-1">2. Produce Honey <a class="header-anchor" href="#_2-produce-honey" aria-label="Permalink to &quot;2. Produce Honey&quot;">​</a></h3><p>Use Bees and Beehives to produce Honey Frames.</p><p>Process the Honey Frames through the <strong>Honey Factory</strong> to create Honey Barrels.</p><p>You need <strong>4 Honey Barrels</strong>, equivalent to <strong>1 Honey Pallet</strong>, for one Honey Oatmeal batch.</p><h3 id="_3-grow-oats" tabindex="-1">3. Grow Oats <a class="header-anchor" href="#_3-grow-oats" aria-label="Permalink to &quot;3. Grow Oats&quot;">​</a></h3><p>Purchase Oat Seeds from FarmCo and plant them.</p><p>Oats take approximately <strong>8 minutes</strong> to fully grow without any growth-speed multipliers.</p><h3 id="_4-harvest-the-oats" tabindex="-1">4. Harvest the Oats <a class="header-anchor" href="#_4-harvest-the-oats" aria-label="Permalink to &quot;4. Harvest the Oats&quot;">​</a></h3><p>Harvest the fully grown Oats using your farming equipment.</p><p>You need <strong>100 harvested Oats</strong> for one Honey Oatmeal pallet.</p><h3 id="_5-load-the-honey-oatmeal-factory" tabindex="-1">5. Load the Honey Oatmeal Factory <a class="header-anchor" href="#_5-load-the-honey-oatmeal-factory" aria-label="Permalink to &quot;5. Load the Honey Oatmeal Factory&quot;">​</a></h3><p>Place the required materials into the Honey Oatmeal Factory:</p><p><strong>1 Honey Pallet + 100 Harvested Oats</strong></p><p>The Honey counter represents Honey Barrels, so one Honey Pallet appears as <strong>4 Barrels</strong>.</p><h3 id="_6-start-production" tabindex="-1">6. Start Production <a class="header-anchor" href="#_6-start-production" aria-label="Permalink to &quot;6. Start Production&quot;">​</a></h3><p>Once the required materials have been supplied, operate the factory to begin production.</p><h3 id="_7-collect-the-honey-oatmeal" tabindex="-1">7. Collect the Honey Oatmeal <a class="header-anchor" href="#_7-collect-the-honey-oatmeal" aria-label="Permalink to &quot;7. Collect the Honey Oatmeal&quot;">​</a></h3><p>The finished product is produced as <strong>Honey Oatmeal Bundles</strong>.</p><p>A full pallet contains <strong>27 bundles</strong>.</p><h3 id="_8-sell-the-honey-oatmeal" tabindex="-1">8. Sell the Honey Oatmeal <a class="header-anchor" href="#_8-sell-the-honey-oatmeal" aria-label="Permalink to &quot;8. Sell the Honey Oatmeal&quot;">​</a></h3><p>Take the finished Honey Oatmeal to the appropriate selling location.</p><p>At the maximum documented price:</p><p><strong>27 Bundles × 3,250 Coins = 87,750 Coins</strong>.</p><h2 id="honey-oatmeal-production-chain" tabindex="-1">Honey Oatmeal Production Chain <a class="header-anchor" href="#honey-oatmeal-production-chain" aria-label="Permalink to &quot;Honey Oatmeal Production Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bees</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Honey Frames</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Honey Factory</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Honey Pallet</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>                ┌────────────────────┐</span></span>
<span class="line"><span>Oats ─────────→ │ Honey Oatmeal      │</span></span>
<span class="line"><span>Honey ────────→ │ Factory            │</span></span>
<span class="line"><span>                └─────────┬──────────┘</span></span>
<span class="line"><span>                          ↓</span></span>
<span class="line"><span>                  Honey Oatmeal</span></span>
<span class="line"><span>                          ↓</span></span>
<span class="line"><span>                        Sell</span></span></code></pre></div><blockquote><p><strong>Tip:</strong> Honey Oatmeal is an advanced production chain because it requires both a Honey production setup and an Oat farming setup. It is therefore better suited to players who already have access to Bees, Honey production, and efficient crop farming.</p></blockquote>`,57)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
